{
  "items": [
    {
      "name": "MvPolynomial.pderiv_rename",
      "module_name": "Mathlib.Algebra.MvPolynomial.PDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type v} [inst : CommSemiring R] {τ : Type u_1} {f : σ → τ},\n  Function.Injective f →\n    ∀ (x : σ) (p : MvPolynomial σ R),\n      (MvPolynomial.pderiv (f x)) ((MvPolynomial.rename f) p) = (MvPolynomial.rename f) ((MvPolynomial.pderiv x) p)"
    },
    {
      "name": "Polynomial.taylor_injective",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Ring R] (r : R), Function.Injective ⇑(Polynomial.taylor r)"
    },
    {
      "name": "Polynomial.taylor_coeff",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (r : R) (f : Polynomial R) (n : ℕ),\n  ((Polynomial.taylor r) f).coeff n = Polynomial.eval r ((Polynomial.hasseDeriv n) f)"
    },
    {
      "name": "PowerSeries.subst",
      "module_name": "Mathlib.RingTheory.PowerSeries.Substitution",
      "kind": "definition",
      "type": "{R : Type u_2} →\n  [inst : CommRing R] →\n    {τ : Type u_3} →\n      {S : Type u_4} → [inst_1 : CommRing S] → [Algebra R S] → MvPowerSeries τ S → PowerSeries R → MvPowerSeries τ S"
    },
    {
      "name": "MvPowerSeries.coeff_subst",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommRing R] {τ : Type u_4} {S : Type u_5} [inst_1 : CommRing S]\n  [inst_2 : Algebra R S] {a : σ → MvPowerSeries τ S},\n  MvPowerSeries.HasSubst a →\n    ∀ (f : MvPowerSeries σ R) (e : τ →₀ ℕ),\n      (MvPowerSeries.coeff e) (MvPowerSeries.subst a f) =\n        ∑ᶠ (d : σ →₀ ℕ), (MvPowerSeries.coeff d) f • (MvPowerSeries.coeff e) (d.prod fun s e => a s ^ e)"
    }
  ]
}
